#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int mod = 998244353;
int n;
vector<vector<int>> idx;

bool good(int v, int x, int d, int i) {
    int y = v-1-x;
    int s = n-v+1;
    int l = 1+x;
    int r = n-y;
    if(d == 0) {
        if(l==(i+1)/2 && i<r) return true;
    }
    if((i==2*s-2 || i == 2*s-1) && i >= r) return true;
    if(d == 1) {
        if(r == (n+1+i)/2 && i > l) return true;
    }
    if((i==n+2-2*s || i == n+3-2*s) && i<=l) return true;
    return false;
}

bool allowed(int v, int x, int d) {
    for(int i : idx[v]) {
        if(!good(v, x, d, i)) return false;
    }
    return true;
}

void solve() {
    
    cin >> n;
    vector<int> a(n + 1);
    idx.assign(n + 2, {});
    bool bad = false;
    for(int i = 1;i <= n; i++) {
        cin >> a[i];
        if(a[i] < 1 || a[i] > n) bad = true;
        else idx[a[i]].push_back(i);
    }
    if(bad) {
        cout << 0 << endl;
        return;
    }
    
    vector<ll> f(n + 2, 0), g(n + 2, 0);
    f[0] = 1;
    for(int v = 1; v < n; v++) {
        fill(g.begin(), g.end(), 0);
        for(int x = 0; x <= v - 1; x++) {
            if(f[x] == 0) continue;
            if(allowed(v, x, 0)) {
                g[x+1] = (g[x+1] + f[x]) % mod;
            }
            if(allowed(v, x, 1)) {
                g[x] = (g[x] + f[x]) % mod;
            }
        }
        swap(f, g);
    }
    
    ll ans = 0;
    for(int x = 0; x <= n - 1; x++) {
        if(f[x] == 0) continue;
        if(allowed(n, x, 0)) ans = (ans + f[x]) % mod;
    }
    
    cout << ans << endl;
}

int main() {
	// your code goes here
	int t = 1;
	cin >> t;
	
	while(t--) {
	    solve();
	}
	
	return 0;

}
